--- /dev/null
+++ b/src/features/notes/server/tags.js
@@ -0,0 +1,26 @@
+const MAX_TAGS = 5;
+const MAX_LEN = 20;
+
+export const normalizeTag = (s) => s.trim().toLocaleLowerCase('tr');
+
+// Returns the cleaned tag list, or null when the input breaks the rules (caller answers 400).
+export function parseTags(input) {
+  if (!Array.isArray(input)) return null;
+  const out = new Set();
+  for (const t of input) {
+    if (typeof t !== 'string') return null;
+    const len = [...t.trim()].length;
+    if (len < 1 || len > MAX_LEN) return null;
+    out.add(normalizeTag(t));
+  }
+  // shortcut: limit counts tags after duplicates are dropped, not raw input length
+  return out.size > MAX_TAGS ? null : [...out];
+}
+
+export function countTags(notes) {
+  const counts = new Map();
+  for (const n of notes) for (const t of n.tags) counts.set(t, (counts.get(t) ?? 0) + 1);
+  return [...counts]
+    .map(([tag, count]) => ({ tag, count }))
+    .sort((a, b) => b.count - a.count || a.tag.localeCompare(b.tag, 'tr'));
+}
