@@ -0,0 +1,24 @@
+const MAX_TAGS = 5;
+const MAX_LEN = 20;
+
+// Returns the cleaned tag list, or null when the input breaks the rules.
+export function normalizeTags(tags) {
+  if (!Array.isArray(tags) || tags.length > MAX_TAGS) return null;
+  const out = new Set();
+  for (const t of tags) {
+    if (typeof t !== 'string') return null;
+    const s = t.trim();
+    if (!s || [...s].length > MAX_LEN) return null;
+    out.add(s.toLocaleLowerCase('tr'));
+  }
+  return [...out];
+}
+
+// Tag counts over the given notes: count desc, then alphabetical (Turkish).
+export function countTags(notes) {
+  const counts = new Map();
+  for (const n of notes) for (const tag of n.tags) counts.set(tag, (counts.get(tag) ?? 0) + 1);
+  return [...counts]
+    .map(([tag, count]) => ({ tag, count }))
+    .sort((a, b) => b.count - a.count || a.tag.localeCompare(b.tag, 'tr'));
+}
