+import { test, before, after } from 'node:test';
+import assert from 'node:assert/strict';
+import { createApp } from '../src/app/server.js';
+
+let server, base;
+before(async () => {
+  server = createApp().listen(0);
+  await new Promise((r) => server.once('listening', r));
+  base = `http://127.0.0.1:${server.address().port}`;
+});
+after(() => server.close());
+
+const call = (method, path, user, body) => fetch(base + path, {
+  method, headers: { 'content-type': 'application/json', ...(user ? { 'x-user': user } : {}) }, body: body && JSON.stringify(body),
+});
+const post = async (user, body) => (await call('POST', '/notes', user, { title: 't', ...body })).json();
+
+test('E-01.1 note without tags returns tags: []', async () => {
+  assert.deepEqual((await post('u1', {})).tags, []);
+});
+
+test('E-01.2 tags are trimmed, Turkish-lowercased, deduped, first-seen order kept', async () => {
+  const note = await post('u1', { tags: [' İŞ ', 'Ev', 'iş', 'IRMAK', 'ev'] });
+  assert.deepEqual(note.tags, ['iş', 'ev', 'ırmak']);
+});
+
+test('E-01.3 invalid tags give 400 on POST', async () => {
+  for (const tags of ['iş', [1], [''], ['   '], ['a'.repeat(21)], ['a', 'b', 'c', 'd', 'e', 'f'], null, {}]) {
+    assert.equal((await call('POST', '/notes', 'u1', { title: 't', tags })).status, 400, JSON.stringify(tags));
+  }
+});
+
+test('E-01.4 boundary: 5 tags and 20-char tag are accepted', async () => {
+  const note = await post('u1', { tags: ['a'.repeat(20), 'b', 'c', 'd', 'e'] });
+  assert.equal(note.tags.length, 5);
+});
+
+test('E-01.5 PATCH replaces tags; invalid gives 400 and keeps old; no tags field keeps old', async () => {
+  const note = await post('u1', { tags: ['a', 'b'] });
+  const url = `/notes/${note.id}`;
+  assert.deepEqual((await (await call('PATCH', url, 'u1', { tags: ['C'] })).json()).tags, ['c']);
+  assert.equal((await call('PATCH', url, 'u1', { tags: ['x'.repeat(21)] })).status, 400);
+  assert.deepEqual((await (await call('PATCH', url, 'u1', { title: 'yeni' })).json()).tags, ['c']);
+  assert.deepEqual((await (await call('PATCH', url, 'u1', { tags: [] })).json()).tags, []);
+});
+
+test('E-01.6 GET /notes?tag= filters case-insensitively (Turkish)', async () => {
+  const a = await post('u2', { title: 'a', tags: ['iş'] });
+  await post('u2', { title: 'b', tags: ['ev'] });
+  const got = await (await call('GET', `/notes?tag=${encodeURIComponent('İŞ')}`, 'u2')).json();
