@@ -0,0 +1,20 @@
+const MAX_TAGS = 5;
+const MAX_LENGTH = 20;
+
+export function lowerTr(s) {
+  return s.toLocaleLowerCase('tr');
+}
+
+// Returns the normalized tag list, or null when the input breaks the rules.
+export function normalizeTags(input) {
+  if (!Array.isArray(input)) return null;
+  const out = [];
+  for (const t of input) {
+    if (typeof t !== 'string') return null;
+    const trimmed = t.trim();
+    if (trimmed.length < 1 || trimmed.length > MAX_LENGTH) return null;
+    const tag = lowerTr(trimmed);
+    if (!out.includes(tag)) out.push(tag);
+  }
+  return out.length > MAX_TAGS ? null : out;
+}
